// WEB-002 · Unknown customer shows "Customer not found."
// Requirement: R2 · Priority: P1 · Suites: smoke, regression
// Customer maintenance screen
// Generated by the FlowPilot AI Test Factory (CogenSight)
import { test, expect } from '@playwright/test';

test('R2 unknown customer shows not found', async ({ page }) => {
  await page.goto('https://anupsahoo.github.io/progress-agent/customer-maint');
  await page.getByLabel('Customer number').fill('999999');
  await page.getByRole('button', { name: 'Look up' }).click();
  await expect(page.getByRole('alert')).toHaveText('Customer not found.');
});
